CREATE TABLE crop_batch_snapshots(batch_id BIGINT PRIMARY KEY,crop_id BIGINT,farmer_id BIGINT,initial_quantity NUMERIC(12,2),available_quantity NUMERIC(12,2),reserved_quantity NUMERIC(12,2),sold_quantity NUMERIC(12,2),province VARCHAR(100),expiry_date DATE,status VARCHAR(30),updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE inventory_snapshots(batch_id BIGINT PRIMARY KEY,available_quantity NUMERIC(12,2),reserved_quantity NUMERIC(12,2),sold_quantity NUMERIC(12,2),updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE order_facts(order_id BIGINT PRIMARY KEY,buyer_id BIGINT,total_amount NUMERIC(15,2),status VARCHAR(20),updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE shipment_facts(shipment_id BIGINT PRIMARY KEY,order_id BIGINT,status VARCHAR(20),updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE rescue_facts(registration_id BIGINT PRIMARY KEY,crop_batch_id BIGINT,farmer_id BIGINT,rescue_point_id BIGINT,status VARCHAR(20),updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE processed_events(event_id UUID PRIMARY KEY,processed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE backfill_checkpoints(source VARCHAR(30) PRIMARY KEY,next_page INTEGER NOT NULL DEFAULT 0,completed BOOLEAN NOT NULL DEFAULT FALSE,updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
